<script setup lang="ts">defineProps<{ modelValue?: string }>(); defineEmits<{ 'update:modelValue': [value: string] }>(); const { data } = await useFetch<{ data: any[] }>('/api/admin/media')</script>
<template><FormField label="Media"><select :value="modelValue" class="w-full rounded-2xl border border-stone-200 bg-stone-50 px-4 py-3 text-sm" @change="$emit('update:modelValue', ($event.target as HTMLSelectElement).value)"><option value="">Select media</option><option v-for="item in data?.data" :key="item.id" :value="item.url">{{ item.alt || item.path }}</option></select></FormField></template>